```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int minDiff = 1000000;
    int a = 0, b = 0;
    for (int i = 0; i < (int)dane.size(); i++) {
        for (int j = i + 1; j < (int)dane.size(); j++) {
            int diff = dane[i] - dane[j];
            if (diff < 0) diff = -diff;
            if (diff < minDiff) {
                minDiff = diff;
                a = dane[i];
                b = dane[j];
            }
        }
    }
    cout << "Najblizsza para: (" << a << ", " << b << ")" << endl;
    cout << "Roznica: " << minDiff << endl;
    return 0;
}
```

